'use strict';const context={uid:'fixture-admin',role:'admin',db:'fixture',auth:{uid:'fixture-admin'},route:'dashboard',permissionRevision:1,canReadPayments:true};
const sdk={ref:(_,p)=>p,orderByKey:()=>({order:true}),startAt:after=>({after}),limitToFirst:limit=>({limit}),query:(path,...args)=>({path,args}),get:async spec=>{const response=await fetch('/api/read?spec='+encodeURIComponent(JSON.stringify(spec)),{cache:'no-store'});if(!response.ok)throw Error('No se pudo leer el ejemplo local.');const data=await response.json();return{val:()=>data};}};
const reader=SVCommercialPagesReader.create({sdk,capture:()=>({...context,hidden:document.hidden})});const dlg=document.getElementById('detail');let focused;
function detail(record,row){focused=document.activeElement;dlg.querySelector('h2').textContent=row.number||row.saleNumber||'Cobro';const dl=dlg.querySelector('dl');dl.replaceChildren();const fields=[['Cliente',record.cliente||row.client],['Fecha',record.fecha||row.date],['Importe',SVCommercialPagesView.money(row.totalCents??row.amountCents)],['Detalle',record.observaciones||row.reference||'Registro ficticio de prueba']];for(const[label,value]of fields){const dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=label;dd.textContent=value;dl.append(dt,dd);}dlg.showModal();}
const view=SVCommercialPagesView.create({element:document.getElementById('view'),reader,day:'2026-11-01',onSale:detail,onPayment:detail,canAnnul:()=>true,onAction:async(kind,row)=>{window.fixtureAction={kind,key:row.key};}});window.fixtureView=view;
dlg.querySelector('[data-close]').onclick=()=>dlg.close();dlg.addEventListener('close',()=>focused?.focus());
for(const b of document.querySelectorAll('[data-route]'))b.onclick=()=>{context.route=b.dataset.route;for(const btn of document.querySelectorAll('[data-route]')){if(btn===b)btn.setAttribute('aria-current','page');else btn.removeAttribute('aria-current');}view.show(context.route);};document.querySelector('[data-route=dashboard]').click();
